<?php
require_once dirname(__DIR__).'/app/helpers.php';require_auth();require_once dirname(__DIR__).'/app/Services/ScheduledPaymentService.php';$u=auth_user();$db=Database::connection();$svc=new ScheduledPaymentService($db);$error=null;$success=null;$s=$db->prepare('SELECT a.id,a.account_number,at.currency,at.name type_name FROM accounts a JOIN account_types at ON at.id=a.account_type_id WHERE a.user_id=? AND a.status="active" ORDER BY a.id');$s->execute([(int)$u['id']]);$accounts=$s->fetchAll();$s=$db->prepare('SELECT id,name,category FROM billers WHERE status="active" ORDER BY category,name');$s->execute();$billers=$s->fetchAll();$s=$db->prepare('SELECT id,name,nickname,account_number FROM beneficiaries WHERE user_id=? AND status="active" ORDER BY name');$s->execute([(int)$u['id']]);$beneficiaries=$s->fetchAll();try{if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='create'){$beneficiary=$_POST['target_type']==='beneficiary'?(int)$_POST['beneficiary_id']:null;$biller=$_POST['target_type']==='biller'?(int)$_POST['biller_id']:null;$id=$svc->create((int)$u['id'],(int)$_POST['account_id'],$beneficiary,$biller,$_POST['amount'],$_POST['currency'],$_POST['frequency'],$_POST['next_run_at'],$_POST['description']??'');$success='Scheduled payment #'.$id.' created.';}elseif($action==='status'){$svc->updateStatus((int)$_POST['id'],(int)$u['id'],$_POST['status']);$success='Schedule updated.';}}}catch(Throwable $e){$error=$e->getMessage();}$items=$svc->list((int)$u['id']);$totalBalance=0;$pageTitle='Scheduled Payments';$currentPage='payments';require __DIR__.'/partials/header.php';require __DIR__.'/partials/sidebar.php';?>
<div class="d-flex justify-content-between align-items-center mb-4"><div><h3 class="fw-bold mb-1">Scheduled & Recurring Payments</h3><p class="text-muted mb-0">Automatically execute simulated payments on a schedule.</p></div><a href="<?=url('bill-payments.php')?>" class="btn btn-outline-primary">Bill Payments</a></div>
<?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><div class="row g-4"><div class="col-lg-5"><div class="card border-0 shadow-sm"><div class="card-header bg-white fw-bold">Create Schedule</div><div class="card-body"><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="create"><div class="col-12"><label class="form-label">Debit Account</label><select name="account_id" class="form-select" required><?php foreach($accounts as $a):?><option value="<?=$a['id']?>"><?=e($a['account_number'])?> — <?=e($a['type_name'])?></option><?php endforeach;?></select></div><div class="col-12"><label class="form-label">Payment Type</label><select name="target_type" id="targetType" class="form-select" onchange="toggleTarget()"><option value="biller">Bill / Service</option><option value="beneficiary">Beneficiary Transfer</option></select></div><div class="col-12" id="billerBox"><label class="form-label">Biller</label><select name="biller_id" class="form-select"><?php foreach($billers as $b):?><option value="<?=$b['id']?>"><?=e(ucfirst($b['category']).' — '.$b['name'])?></option><?php endforeach;?></select></div><div class="col-12 d-none" id="beneficiaryBox"><label class="form-label">Beneficiary</label><select name="beneficiary_id" class="form-select"><option value="">Select beneficiary</option><?php foreach($beneficiaries as $b):?><option value="<?=$b['id']?>"><?=e($b['name'].' — '.$b['account_number'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Amount</label><input name="amount" type="number" step="0.01" min="1" class="form-control" required></div><div class="col-md-6"><label class="form-label">Currency</label><input name="currency" value="<?=e(DEFAULT_CURRENCY)?>" maxlength="3" class="form-control" required></div><div class="col-md-6"><label class="form-label">Frequency</label><select name="frequency" class="form-select"><option value="once">Once</option><option value="daily">Daily</option><option value="weekly">Weekly</option><option value="monthly">Monthly</option></select></div><div class="col-md-6"><label class="form-label">First Run</label><input name="next_run_at" type="datetime-local" class="form-control" required></div><div class="col-12"><label class="form-label">Description</label><input name="description" maxlength="255" class="form-control"></div><div class="col-12"><button class="btn btn-primary w-100">Create Schedule</button></div></form></div></div></div><div class="col-lg-7"><div class="card border-0 shadow-sm"><div class="card-header bg-white fw-bold">Your Schedules</div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Target</th><th>Amount</th><th>Frequency</th><th>Next Run</th><th>Status</th><th></th></tr></thead><tbody><?php if(!$items):?><tr><td colspan="6" class="text-center text-muted py-4">No scheduled payments.</td></tr><?php else:foreach($items as $p):?><tr><td><?=e($p['biller_name']??$p['beneficiary_name']??'—')?><div class="small text-muted"><?=e($p['beneficiary_account']??'Service payment')?></div></td><td>$<?=number_format((float)$p['amount'],2)?></td><td><?=e($p['frequency'])?></td><td class="small"><?=e($p['next_run_at'])?></td><td><span class="badge text-bg-<?=in_array($p['status'],['active'])?'success':($p['status']==='paused'?'warning':'secondary')?>"><?=e($p['status'])?></span></td><td><?php if(in_array($p['status'],['active','paused'])):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$p['id']?>"><input type="hidden" name="status" value="<?=$p['status']==='active'?'paused':'active'?>"><button class="btn btn-sm btn-outline-primary"><?=$p['status']==='active'?'Pause':'Resume'?></button></form><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></div><div class="alert alert-info mt-3 small">Scheduled execution is simulated. Run the scheduler command from cron/task scheduler; no real payment network is contacted.</div></div></div><script>function toggleTarget(){const t=document.getElementById('targetType').value;document.getElementById('billerBox').classList.toggle('d-none',t!=='biller');document.getElementById('beneficiaryBox').classList.toggle('d-none',t!=='beneficiary')}toggleTarget();</script><?php require __DIR__.'/partials/footer.php';?>
